class _Pose:
    def compose(self, b: Pose) -> Pose:
        return pose_compose(self, b)
    def inverse(self) -> Pose:
        return pose_inverse(self)
    def between(self, b: Pose) -> Pose:
        return pose_between(self, b)
    def apply(self, point: Double3) -> Double3:
        return pose_apply(self, point)
    def apply_inverse(self, point: Double3) -> Double3:
        return pose_apply_inverse(self, point)
    def apply_points(self, points: Sequence[Double3]) -> List[Double3]:
        return pose_apply_points(self, points)
    def interpolate(self, b: Pose, t: float) -> Pose:
        return pose_interpolate(self, b, t)
    @staticmethod
    def from_points(origin: Double3, on_x: Double3, in_xy: Double3) -> Pose:
        return pose_from_points(origin, on_x, in_xy)
    @staticmethod
    def look_at(eye: Double3, target: Double3, up: Double3) -> Pose:
        return pose_look_at(eye, target, up)
    def to_matrix4x4(self) -> Matrix4x4:
        return matrix4x4_from_pose(self)
    def to_pose2d(self) -> Pose2D:
        return pose2d_from_pose(self)
    def integrate(self, body: Twist, dt: float) -> Pose:
        return pose_integrate(self, body, dt)
    def __mul__(self, other):
        if isinstance(other, Pose):
            return pose_compose(self, other)
        if isinstance(other, Double3):
            return pose_apply(self, other)
        return NotImplemented


